ST.xhtml:
// === IMPLEMENTATION ===

{region "§1 Gain actif (toujours calculé — réglage pur, indépendant d'Enable)"}
DistanceP2PV_M := PosP2_M - PosPV_M;
IF (DistanceP2PV_M > 0.0) AND (CalibFreq_Hz > 0.0) AND (CalibTime_S > 0.0) THEN
    CalibGain := DistanceP2PV_M / (CalibFreq_Hz * CalibTime_S);
    CalibValid := (CalibGain >= CST_GainMin) AND (CalibGain <= CST_GainMax);
ELSE
    CalibGain := 0.0;
    CalibValid := FALSE;
END_IF;

IF CalibValid THEN
    GainActive := CalibGain;
ELSE
    // Repli borné : un repli nul/aberrant figerait l'estimateur (et le chariot simulé).
    GainActive := LIMIT(CST_GainMin, FallbackGain, CST_GainMax);
END_IF;
{endregion}

{region "§2 Gate mesure"}
// Fronts évalués à chaque scan, y compris hors Enable : aucun front périmé à la réactivation.
EdgeUpP2(CLK := SensorP2);   EdgeDnP2(CLK := SensorP2);
EdgeUpPV(CLK := SensorPV);   EdgeDnPV(CLK := SensorPV);

IF NOT Enable THEN
    MeasureActive := FALSE;
    RETURN;
END_IF;

CycleTimeCalc(DefaultValueS := 0.010);
FreqSample_Hz := LIMIT(0.0, DriveActualFreq_Hz, CST_FreqMax_Hz);
{endregion}

{region "§3 Mesure proposée P2 <-> PV (jamais appliquée)"}
// Mot thermomètre (TRUE si position <= cote) :
//   vers la Trémie      : P2 monte puis PV monte ;
//   vers la Maintenance : PV descend puis P2 descend.
// Seul le 1er front compte : les rebonds du capteur de départ (vu -> perdu -> retrouvé) sont
// ignorés une fois la mesure lancée ; la mesure ne se termine que sur le front ATTENDU.
IF NOT MeasureActive THEN
    IF EdgeUpP2.Q OR EdgeDnPV.Q THEN
        MeasureActive := TRUE;
        MeasureTowardTremie := EdgeUpP2.Q;
        ElapsedS := 0.0;
        FreqIntegral_HzS := 0.0;
        FreqMin_Hz := FreqSample_Hz;
        FreqMax_Hz := FreqSample_Hz;
    END_IF;
ELSE
    ElapsedS := ElapsedS + CycleTimeCalc.CycleTimeS;
    FreqIntegral_HzS := FreqIntegral_HzS + FreqSample_Hz * CycleTimeCalc.CycleTimeS;
    FreqMin_Hz := MIN(FreqMin_Hz, FreqSample_Hz);
    FreqMax_Hz := MAX(FreqMax_Hz, FreqSample_Hz);

    MeasureEnd := (MeasureTowardTremie AND EdgeUpPV.Q) OR (NOT MeasureTowardTremie AND EdgeDnP2.Q);

    IF MeasureEnd THEN
        MeasureActive := FALSE;
        MeasuredTime_S := ElapsedS;
        MeasuredFreqSpread_Hz := FreqMax_Hz - FreqMin_Hz;
        IF ElapsedS > 0.0 THEN
            MeasuredFreqAvg_Hz := FreqIntegral_HzS / ElapsedS;
        ELSE
            MeasuredFreqAvg_Hz := 0.0;
        END_IF;
        IF (FreqIntegral_HzS > 0.0) AND (DistanceP2PV_M > 0.0) THEN
            MeasuredGain := DistanceP2PV_M / FreqIntegral_HzS;
        ELSE
            MeasuredGain := 0.0;
        END_IF;
        MeasureCount := MeasureCount + 1;
    ELSIF (FreqSample_Hz < CST_MeasureMinFreq_Hz) OR (ElapsedS > CST_MeasureTimeout_S) THEN
        // Arrêt ou trajet interrompu : mesure abandonnée, dernier résultat publié conservé.
        MeasureActive := FALSE;
    END_IF;
END_IF;
{endregion}

{region "§1 Acquisition temps"}
// 1. ACQUISITION DU TEMPS SYSTÈME
TimeCurrent := TIME();
{endregion}

{region "§2 Initialisation"}
// 2. INITIALISATION UNIQUE AU PREMIER CYCLE
IF NOT InitDone THEN
    TimeLast := TimeCurrent;
    InitDone := TRUE;
    CycleTimeS := DefaultValueS;
    RETURN;
END_IF;
{endregion}

{region "§3 Calcul delta"}
// 3. CALCUL DU DELTA EN MILLISECONDES
DeltaTimeMs := TIME_TO_UDINT(TimeCurrent - TimeLast);
{endregion}

{region "§4 Conversion, secours et bornage"}
// 4. CONVERSION EN SECONDES, AVEC DOUBLE BORNAGE DU DELTA
//
// TIME() est un compteur systeme 32 bits en millisecondes depuis le demarrage de
// l'automate. Il n'est PAS absolu : il reboucle a 0 tous les 2^32 ms (~49,7 jours).
// La soustraction TimeCurrent - TimeLast est modulo 2^32 : au passage du rebouclage,
// tant que l'ecart reel entre deux scans reste < 49,7 j (toujours vrai a 10 ms),
// DeltaTimeMs reste correct. Le rebouclage seul n'est donc pas le risque principal.
//
// Le vrai risque est un DeltaTimeMs REELLEMENT > CST_MaxCycleDeltaMs : reprise apres
// un online-change, sortie d'un point d'arret / pas-a-pas debug, ou fenetre du
// rebouclage TIME(). Le chien de garde tache (200 ms, sensibilite 1) borne deja les
// gels en fonctionnement ; ce plafond couvre les cas hors surveillance.
// Un dt aberrant publie tel quel donnerait un CycleTimeS enorme, propage en un seul
// scan dans les rampes de vitesse et les integrateurs de position/frein -> saut
// physique. Fail-safe : hors de la plage nominale (0 < dt <= plafond), on publie la
// valeur de secours DefaultValueS au lieu de l'artefact. Pas de redemarrage auto.
//
// Borne basse dt = 0 (anti-zero, ex. premier appel du scan) et borne haute
// dt > CST_MaxCycleDeltaMs (anti-artefact) partagent la meme branche de secours.
IF (DeltaTimeMs > 0) AND (DeltaTimeMs <= CST_MaxCycleDeltaMs) THEN
    CycleTimeS := UDINT_TO_REAL(DeltaTimeMs) / 1000.0;
ELSE
    CycleTimeS := DefaultValueS;
END_IF;
{endregion}

{region "§5 Archivage"}
// 5. ARCHIVAGE POUR LE PROCHAIN CYCLE
TimeLast := TimeCurrent;
{endregion}
